command:
Set-Location 'E:/OptoJump/IronJump-gil-waiter-first-20261019-01'
if((Get-FileHash plan01.json).Hash.ToLower() -ne '76a90373d5df1bdcca768f59575118196100eb581324e85c38c3bef065b807cd'){throw 'Plan mismatch'}
if(Test-Path runs){throw 'Unexpected existing runs directory; do not overwrite'}
if(@(Get-CimInstance Win32_Process|Where-Object {$_.Name -eq 'python.exe' -or $_.Name -eq 'ironjump-gil-waiter-first.exe'}).Count){throw 'Live target; no start'}
New-Item -ItemType Directory runs|Out-Null
$p=Start-Process D:/conda/python.exe -ArgumentList 'E:/OptoJump/IronJump-gil-waiter-first-20261019-01/positive_control.py --plan E:/OptoJump/IronJump-gil-waiter-first-20261019-01/plan01.json --tool E:/OptoJump/IronJump-gil-waiter-first-20261019-01/target/release/ironjump-gil-waiter-first.exe --dll E:/OptoJump/IronJump-gil-waiter-first-20261019-01/positive_oracle.dll --output E:/OptoJump/IronJump-gil-waiter-first-20261019-01/runs/positive01' -WorkingDirectory 'E:/OptoJump/IronJump-gil-waiter-first-20261019-01' -Wait -PassThru -RedirectStandardOutput positive_control02.stdout -RedirectStandardError positive_control02.stderr
@{positive_exit=$p.ExitCode;utc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content positive_execution02.json -Encoding UTF8
if($p.ExitCode -ne 0){throw 'Positive control failed; preserve evidence'}
$n=Start-Process D:/conda/python.exe -ArgumentList 'E:/OptoJump/IronJump-gil-waiter-first-20261019-01/negative_control.py' -WorkingDirectory 'E:/OptoJump/IronJump-gil-waiter-first-20261019-01' -Wait -PassThru -RedirectStandardOutput negative_control01.stdout -RedirectStandardError negative_control01.stderr
@{positive_exit=$p.ExitCode;negative_exit=$n.ExitCode;utc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Compress
if($n.ExitCode -ne 0){throw 'Negative control failed; preserve evidence'}
